}

// ASP.NET Core implementation
public sealed class HttpContextUserProvider(IHttpContextAccessor accessor) : IUserContextProvider
{
    public string GetCurrentUserId()
    {
        var user = accessor.HttpContext?.User;

        // Try common claim types
        return user?.FindFirst("sub")?.Value       // OpenID Connect
            ?? user?.FindFirst("oid")?.Value       // Azure AD
            ?? user?.FindFirst("user_id")?.Value   // Custom
            ?? user?.Identity?.Name                // Fallback
            ?? "system";                           // Background jobs
    }

    public string? GetCorrelationId()
    {
        var context = accessor.HttpContext;

        // Check headers first
        if (context?.Request.Headers.TryGetValue("X-Correlation-ID", out var correlationId) == true)
            return correlationId.ToString();

        if (context?.Request.Headers.TryGetValue("X-Request-ID", out var requestId) == true)
            return requestId.ToString();

        // Fall back to OpenTelemetry trace ID
        return System.Diagnostics.Activity.Current?.TraceId.ToString();
    }
}

// Background job implementation
public sealed class BackgroundJobUserProvider : IUserContextProvider
{
    public string GetCurrentUserId() => "system-job";
    public string? GetCorrelationId() => System.Diagnostics.Activity.Current?.TraceId.ToString();
}

public sealed class Customer : IAuditableEntity<CustomerId>
{
    public CustomerId Id { get; private init; }
    public string Name { get; private set; } = string.Empty;

    // Audit fields - set by repository
    public DateTimeOffset CreatedAt { get; private set; }
    public string CreatedBy { get; private set; } = string.Empty;
    public DateTimeOffset? UpdatedAt { get; private set; }
    public string? UpdatedBy { get; private set; }
    public long Version { get; private set; }

    public static Customer Create(string name) => new()
    {
        Id = CustomerId.New(),
        Name = name
    };
}

// Define a strongly-typed ID
public readonly record struct CustomerId(Guid Value);

// Implement IEntity with the strongly-typed ID
public sealed class Customer : IEntity<CustomerId>
{
    public CustomerId Id { get; private init; }
    public string Name { get; private set; } = string.Empty;
}

public sealed class Customer : IAuditableEntity<CustomerId>, ISoftDeletable
{
    public CustomerId Id { get; private init; }

    // Soft delete fields - set by repository
    public bool IsDeleted { get; private set; }
    public DateTimeOffset? DeletedAt { get; private set; }
    public string? DeletedBy { get; private set; }
}

// When calling DeleteAsync, the entity is soft-deleted:
await repository.DeleteAsync(customerId, cancellationToken);
// IsDeleted = true, DeletedAt = now, DeletedBy = current user

// Subsequent queries automatically exclude soft-deleted entities:
var result = await repository.GetByIdAsync(customerId, cancellationToken);
// Returns Error.NotFound because entity is soft-deleted

// Default: page 1, 20 items
var request = new PagedRequest();

// Custom pagination
var request = new PagedRequest(Page: 2, PageSize: 50);

// PageSize is automatically clamped to MaxPageSize
var request = new PagedRequest(PageSize: 500);  // Becomes 100

// Page is automatically clamped to minimum 1
var request = new PagedRequest(Page: 0);  // Becomes 1

// Navigate pages
var nextPage = request.NextPage();
var prevPage = request.PreviousPage();

// Page 1, size 20 -> Skip 0
// Page 2, size 20 -> Skip 20
// Page 3, size 20 -> Skip 40
var skip = request.Skip;

var result = await repository.GetPagedAsync(request, ct);

result.Match(
    success: paged =>
    {
        Console.WriteLine($"Page {paged.Page} of {paged.TotalPages}");
        Console.WriteLine($"Showing {paged.Items.Count} of {paged.TotalCount} items");

        foreach (var item in paged.Items)
        {
            Console.WriteLine(item);
        }

        if (paged.HasNextPage)
        {
            var nextPageRequest = request.NextPage();
            // Fetch next page...
        }
    },
    failure: error => Console.WriteLine($"Error: {error.Message}")
);

// Map to DTOs
PagedResult<CustomerDto> dtos = paged.Map(c => new CustomerDto(c));

