public class CustomerQueryHandler(IReadOnlyRepository<Customer, CustomerId> repository)
{
    public async Task<CustomerDto?> Handle(GetCustomerQuery query, CancellationToken ct)
    {
        var result = await repository.GetByIdAsync(query.CustomerId, ct);

        return result.Match(
            success: customer => new CustomerDto(customer),
            failure: _ => null
        );
    }
}

