// Repository method returning Unit
public async Task<Result<Unit>> DeleteAsync(CustomerId id, CancellationToken ct)
{
    // ... perform delete ...
    return Unit.Value;  // Implicit conversion to Result<Unit>.Success
}

// Controller usage
var result = await repository.DeleteAsync(id, ct);
return result.Match(
    success: _ => NoContent(),
    failure: error => Problem(error.Message)
);

