await using var tx = await unitOfWork.BeginTransactionAsync(ct);
try
{
    await repo1.AddAsync(entity1, ct);
    await repo2.AddAsync(entity2, ct);
    await tx.CommitAsync(ct);
}
catch
{
    await tx.RollbackAsync(ct);
    throw;
}

example.code:
public class CustomerOnboardingService(
    IUnitOfWork unitOfWork,
    IRepository<Customer, CustomerId> customerRepo,
    IRepository<Subscription, SubscriptionId> subscriptionRepo)
{
    public async Task<Result<Customer>> OnboardAsync(
        CreateCustomerCommand cmd,
        CancellationToken ct)
    {
        // Start a transaction
        await using var tx = await unitOfWork.BeginTransactionAsync(ct);

        try
        {
            // Create customer
            var customer = Customer.Create(cmd.Name, cmd.Email);
            var customerResult = await customerRepo.AddAsync(customer, ct);

            if (!customerResult.IsSuccess)
            {
                await tx.RollbackAsync(ct);
                return customerResult;
            }

            // Create subscription
            var subscription = Subscription.CreateTrial(customer.Id);
            var subResult = await subscriptionRepo.AddAsync(subscription, ct);

            if (!subResult.IsSuccess)
            {
                await tx.RollbackAsync(ct);
                return Result.Failure<Customer>(subResult.Error!);
            }

            // Commit both operations atomically
            await tx.CommitAsync(ct);
            return customerResult;
        }
        catch (Exception)
        {
            await tx.RollbackAsync(ct);
            throw;
        }
    }
}

// Recommended pattern using await using
await using var tx = await unitOfWork.BeginTransactionAsync(ct);
// ... operations ...
await tx.CommitAsync(ct);
// tx is automatically disposed even if an exception occurs
